  "criteria": {
    "definition": {
      "assessment": "sufficient",
      "reason": "动机、对象与存储身份、字节范围版本、访问模式、地址资格和内容资格均有定义；内容更新与槽复用的代次变化得到区分。",
      "evidence": [
        {
          "path": "knowledge/hardware/shared-memory-paths.md",
          "quote": "首次 OVERWRITE 可以没有 valid，但必须具备 addr；READ 同时需要两者。映射能力存在只是允许准备，不表示准备已经完成。"
        },
        {
          "path": "knowledge/hardware/shared-memory-paths.md",
          "quote": "副本有效性需要匹配被消费范围的 ν，不能要求所有字节具有相同标签，也不能只检查对象的全局 v。"
        }
      ]
    },
    "legality": {
      "assessment": "sufficient",
      "reason": "明确了四类路径的能力、范围、权限、可见性与生存期条件，并区分平台保证和保守协议选择。CUDA 映射限制、首次触碰供页及 PyTorch 两种非并发图池共享情形与所供来源相符。",
      "evidence": [
        {
          "path": "knowledge/hardware/shared-memory-paths.md",
          "quote": "所有内部复制的源和目的也必须满足各自的地址资格，不能只检查最终消费者。"
        },
        {
          "path": "knowledge/hardware/shared-memory-paths.md",
          "quote": "目标在复制写入完成之前不能被消费者读取，覆盖目标还要等它的旧读者结束。"
        }
      ]
    },
    "algorithm": {
      "assessment": "partial",
      "reason": "A02 已修复：地址准备无条件执行，首次 OVERWRITE 有独立地址不变量和故障变体。版本失效、完成清账、取消排空及复用也有展开。但允许并行的逻辑 READ 可以分别向同一物理目标提交重叠补复制，算法未给内部目标写入与其他内部写入、消费者读取之间建立冲突准入或完成依赖，见 A03。",
      "evidence": [
        {
          "path": "knowledge/hardware/shared-memory-paths.md",
          "quote": "对每种模式都先准备地址，不以是否需要旧内容为条件："
        },
        {
          "path": "knowledge/hardware/shared-memory-paths.md",
          "quote": "READ 可以并行；OVERWRITE、UPDATE 与任何活动逻辑访问互斥。"
        },
        {
          "path": "knowledge/hardware/shared-memory-paths.md",
          "quote": "登记内部源读、目标写和完成票据，再提交复制"
        }
      ]
    },
    "cost": {
      "assessment": "sufficient",
      "reason": "同一轨迹下分别核算复制、消费者读取、远端事务和页迁移；阈值推导、量纲、适用域与设定数值一致。六类成本、共享资源、物理身份去重及重叠条件均有说明。",
      "evidence": [
        {
          "path": "knowledge/hardware/shared-memory-paths.md",
          "quote": "T_copy≈D/B_l+R·x·D/B_d+E_copy，"
        },
        {
          "path": "knowledge/hardware/shared-memory-paths.md",
          "quote": "统一页大小 g 时，M=Σ_p m_p 是总页迁移事件数，Q_mig=M·g，不能再乘触及页数 N_p。"
        },
        {
          "path": "knowledge/hardware/shared-memory-paths.md",
          "quote": "同一主机页被 CPU 和 GPU 映射只计一次容量；锁页状态本身不产生第二份数据。"
        }
      ]
    },
    "adaptation": {
      "assessment": "sufficient",
      "reason": "重复读取、稀疏范围、只写输出、交替改写、页大小、容量和平台能力变化均连接到保留的不变量与需要重算或放弃的条件，未将设定交点外推到不同工作量。",
      "evidence": [
        {
          "path": "knowledge/hardware/shared-memory-paths.md",
          "quote": "局部复制、缓存改变、写后补复制、方向不同的链路带宽或 β≠1 都应回到 Q_c、Q_d、Q_remote 原式，不沿用这个交点。"
        },
        {
          "path": "knowledge/hardware/shared-memory-paths.md",
          "quote": "可去掉被完整覆盖范围的旧内容恢复；仍计准备和实际写流量"
        }
      ]
    },
    "diagnosis": {
      "assessment": "sufficient",
      "reason": "提供了具体竞争解释、可控干预、预测及反证后的修正。检查具有不同表示的参考和实际故障注入；正文明确限制 CPU 模型的证明范围。现有检查遗漏的内部复制并发由 A03 单独处理。",
      "evidence": [
        {
          "path": "knowledge/hardware/shared-memory-paths.md",
          "quote": "固定有用字节分别改变连续性与页布局，分别记录数据链路字节和翻译事件；只有翻译变化时不归因于整页数据传输"
        },
        {
          "path": "knowledge/hardware/shared-memory-paths.md",
          "quote": "正确性检查应把错误变体送入同一参考或状态不变量。"
        }
      ]
    }
  },
  "findings": [
    {
      "id": "K-HW-013-A03",
      "criterion": "algorithm",
      "evidence": "当前正文允许“READ 可以并行”，授权 READ 仅要求“writer 为空”。需要旧内容时，各访问分别“找出目标表示中缺少所需 ν 的范围”，随后“登记内部源读、目标写和完成票据，再提交复制”，消费者只“依赖全部必要复制完成”。正文还说明“内部复制在父预约之下登记物理源读和目标写，不把它误作新的逻辑内容写者”。这些步骤没有规定重叠 pending 复制如何合并或排序，也没有规定新内部目标写如何等待其他父访问的物理读者。",
      "impact": "同一阶段两个不同队列上的 GPU READ 可以同时获准，且都在同一设备表示的相同范围缺少 valid。两者可以各自提交 H→D 补复制。第一份复制完成后，第一个 READ 开始读取 D，而第二份复制仍可写 D，形成物理 RAW/WAR 冲突；两份复制本身也可能形成 WAW 冲突。逻辑访问均为 READ，因此现有 writer/active_readers 检查不能阻止它。写入相同版本或相同数值不能使无序并发访问合法。",
      "blocking": true,
      "required_revision": "为内部移动补足物理范围的冲突准入与完成关系。可将同一目标、epoch、范围和版本的恢复合并为共享 pending 任务，让全部消费者等待同一完成；或保守串行化相关恢复与消费。明确内部目标写必须等待重叠的物理读写责任，消费者必须等待所有可能写其范围的移动，且不能等待自己的未来父访问形成自依赖。增加两个并行逻辑 READ、共享失效设备范围、不同队列及乱序复制完成的轨迹；用独立物理访问不变量拒绝删除该保护后的复制/读取重叠。"
    }
  ],
  "limitations": [
    "所供实际预检仅证明绑定脚本中的确定性 CPU 模型运行成功，不证明 CUDA/MLX 的硬件可见性、真实映射权限、远端事务、TLB、迁移策略、图重放、物理重叠或性能。",
    "完整 phase/DAG 调度器、任意异步交错、准备失败和部分提交失败未被模型穷尽；其中 A03 是当前算法的具体缺口，不能仅作为模型范围限制关闭。",
    "本次依据任务提供的文本和执行记录审查，没有重新执行 Python、重算文件哈希或检查离线链接目标存在性；documents 中哈希按要求采用给定绑定值。",
    "未读取 reader.html、源码归档、CUDA 指南全文或摘录范围之外的相关章节；没有 Agent 使用效果证据。"
  ],
